// Map incoming form fields to the canonical lead schema used across every phase
const body = $input.item.json.body || $input.item.json;
return {
  json: {
    company: body.company || '',
    domain: (body.website || '').replace(/^https?:\/\//,'').replace(/\/$/,''),
    contact_name: body.name || '',
    email: body.email || '',
    phone: body.phone || '',
    country: body.country || '',
    source: 'webform',
    utm_source: body.utm_source || '',
    utm_medium: body.utm_medium || '',
    utm_campaign: body.utm_campaign || '',
    stage: 'Raw Lead'
  }
};

// Scraper service is expected to return an array of raw lead objects
const items = $input.all();
const out = [];
for (const item of items) {
  const rows = Array.isArray(item.json) ? item.json : (item.json.results || [item.json]);
  for (const r of rows) {
    out.push({
      json: {
        company: r.company || '',
        domain: (r.website || '').replace(/^https?:\/\//,'').replace(/\/$/,''),
        contact_name: r.contact_name || '',
        email: r.email || '',
        phone: r.phone || '',
        country: r.country || '',
        source: 'scraper',
        stage: 'Raw Lead'
      }
    });
  }
}
return out;

const r = $input.item.json;
const isReachable = r.is_reachable === 'safe' || r.is_reachable === 'risky';
return {
  json: {
    ...$('Is Duplicate?').item.json,
    email_valid: isReachable,
    email_check_detail: r.is_reachable || 'unknown'
  }
};

const lead = $('Mark Cleaned & Verified').item.json;
const org = $input.item.json.organization || {};
return {
  json: {
    ...lead,
    industry: org.industry || '',
    employee_count: org.estimated_num_employees || null,
    revenue_range: org.annual_revenue_printed || '',
    linkedin_url: org.linkedin_url || '',
    tech_stack: (org.technologies || []).join(', '),
    recent_news: (org.news_articles || []).slice(0,3).map(a => a.title).join(' | '),
    enrichment_status: org.id ? 'Enriched' : 'Research Needed'
  }
};

const lead = $input.item.json;
const roles = ['founder','ceo','marketing director','sales director','operations director'];
return roles.map(role => ({ json: { ...lead, target_role: role } }));

const p = ($input.item.json.people || [])[0];
if (!p) return [];
return {
  json: {
    role_target: $input.item.json.target_role,
    name: p.name || '',
    title: p.title || '',
    email: p.email || '',
    linkedin_url: p.linkedin_url || '',
    phone: (p.phone_numbers && p.phone_numbers[0]) || ''
  }
};

// Rule-based scoring - swap for a call to your self-hosted Ollama endpoint
// (SCORING_ENGINE_URL env var) once local-LLM scoring is ready.
const l = $input.item.json;
let score = 0;
const tier1 = ['united states','united kingdom','canada','australia'];
if (tier1.includes((l.country || '').toLowerCase())) score += 2;
if (l.employee_count >= 11 && l.employee_count <= 200) score += 2;
if ((l.decision_makers || []).length >= 1) score += 2;
if ((l.recent_news || '').length > 0) score += 2;
if (l.enrichment_status === 'Enriched') score += 2;
let tier = 'Disqualified';
if (score >= 8) tier = 'Hot';
else if (score >= 5) tier = 'Warm';
else if (score >= 1) tier = 'Cold';
return { json: { ...l, lead_score: score, score_tier: tier } };

