const lead = $input.item.json;
const steps = [
  {day: 0,  type: 'intro',        wait_hours: 72},
  {day: 3,  type: 'value',        wait_hours: 96},
  {day: 7,  type: 'case_study',    wait_hours: 168},
  {day: 14, type: 'final_followup', wait_hours: 0}
];
return steps.map(s => ({ json: { ...lead, ...s } }));

const lead = $('Follow-up Sequence Loop').item.json;
const ai = $input.item.json.response;
const templates = {
  intro: `Hi ${lead.contact_name}, noticed ${lead.company} might benefit from our services given your work in ${lead.industry}. Open to a quick chat?`,
  value: `Hi ${lead.contact_name}, following up with a resource relevant to ${lead.company}'s space - happy to share more if useful.`,
  case_study: `Hi ${lead.contact_name}, sharing a quick case study similar to ${lead.company}'s situation. Worth a look?`,
  final_followup: `Hi ${lead.contact_name}, last note from me - happy to reconnect whenever timing works better.`
};
return { json: { ...lead, email_body: ai || templates[lead.type] || templates.intro } };

const text = ($input.item.json.body?.reply_text || '').toLowerCase();
let category = 'Interested';
if (/unsubscribe|stop|remove me/.test(text)) category = 'Not Interested';
else if (/out of office|ooo|on leave|on vacation/.test(text)) category = 'OOO';
else if (/not now|no budget|too expensive|competitor/.test(text)) category = 'Objection';
else if (/interested|let's talk|book a call|schedule/.test(text)) category = 'Interested';
return { json: { ...$('Follow-up Sequence Loop').item.json, reply_category: category, reply_text: text } };

