const raw = ($json.lost_reason || 'Unspecified').toLowerCase();
const map = {
  price: 'Price', cost: 'Price', expensive: 'Price',
  competitor: 'Competitor', 'chose competitor': 'Competitor',
  budget: 'No Budget', 'no budget': 'No Budget',
  timing: 'Timing', 'not now': 'Timing', 'bad timing': 'Timing',
  'not interested': 'No Response', 'no response': 'No Response'
};
let normalized = 'Unspecified';
for (const [key, val] of Object.entries(map)) {
  if (raw.includes(key)) { normalized = val; break; }
}
if (normalized === 'Unspecified' && ['Price','Competitor','No Budget','Timing','No Response'].includes($json.lost_reason)) {
  normalized = $json.lost_reason;
}
return { ...$json, lost_reason_normalized: normalized };

