const items = [
  'Send kickoff call invite',
  'Collect billing details',
  'Provision account access',
  'Share onboarding docs',
  'Schedule 30-day check-in'
];
return items.map(task => ({
  company: $json.company,
  email: $json.email,
  task,
  status: 'Pending',
  created_at: new Date().toISOString()
}));

const months = Number($env.CONTRACT_LENGTH_MONTHS || 12);
const renewalDate = new Date();
renewalDate.setMonth(renewalDate.getMonth() + months);
return {
  ...$json,
  renewal_date: renewalDate.toISOString().slice(0, 10),
  reminder_type: 'Renewal'
};
